import { lazy } from 'react';
import { BookOpen as IcBookOpen, Grid3x3 as IcGrid3x3, ListOrdered as IcListOrdered, Mail as IcMail } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Catalog & Knowledge — hub page for the Service Desk menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 4 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'ServiceCatalogCenter'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const ServiceMasterIPS = lazy(() => import('./ServiceMasterIPS'));
const ServiceMaster = lazy(() => import('./ServiceMaster'));
const KnowledgeBase = lazy(() => import('./KnowledgeBase'));
const SupportMailbox = lazy(() => import('./SupportMailbox'));

export const TABS = [
  { id: 'ips', label: 'Service Master', icon: IcGrid3x3, page: 'ServiceMasterIPS', Component: ServiceMasterIPS },
  { id: 'catalog', label: 'Service Catalog', icon: IcListOrdered, page: 'ServiceMaster', Component: ServiceMaster },
  { id: 'kb', label: 'Knowledge Base', icon: IcBookOpen, page: 'KnowledgeBase', Component: KnowledgeBase },
  { id: 'mailbox', label: 'Email to Case', icon: IcMail, page: 'SupportMailbox', Component: SupportMailbox },
];

export default function ServiceCatalogCenter({ setPage }) {
  return (
    <TabHub
      icon={IcBookOpen}
      eyebrow="Service Desk"
      title="Catalog & Knowledge"
      subtitle="The IPS field-service grid, the rate card, the knowledge base and inbound mail"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
